  if (i < 0) return [];
  return [[t.slice(0, i), t.slice(i + 1).replace(/^["']|["']$/g, '')]];
}));
const headers = { authorization: `Bearer ${env.NEATLOGS_TOKEN}`, 'x-project-id': env.NEATLOGS_PROJECT_ID };
let url = 'https://app.neatlogs.com/api/v1/public/traces';
const all = [];
for (let page = 0; page < 10 && url; page++) {
  const r = await fetch(url, { headers });
  if (!r.ok) throw new Error(`${r.status} ${await r.text()}`);
  const j = await r.json();
  const traces = j.data?.traces ?? [];
  all.push(...traces);
  const cursor = j.data?.page?.nextCursor;
  url = cursor ? `https://app.neatlogs.com/api/v1/public/traces?cursor=${encodeURIComponent(cursor)}` : '';
}
const start = Date.parse('2026-10-10T17:55:00Z');
const end = Date.parse('2026-10-10T18:20:00Z');
