+  const fg = (value: number) => value === 2 ? orange : colour === 'none' ? '' : '\x1b[39m';
+  const bg = (value: number) => value === 2 ? orange.replace('[38;', '[48;').replace('[91m', '[101m') : '\x1b[49m';
